ent, { schema });\n\treturn { client, db, ownsConnection: false };\n}\n\nexport function createSqliteDbRuntime(env: AppEnv): DbRuntime {\n\tconst connection = createDbConnection(env.databaseUrl);\n\treturn {\n\t\tdb: connection.db,\n\t\tconnection,\n\t\tclose: () => {\n\t\t\tif (connection.ownsConnection) {\n\t\t\t\tconnection.client.close();\n\t\t\t}\n\t\t},\n\t};\n}\n\n/**\n * 接続を確立する\n */\nexport async function connectDb(client: Database) {\n\tclient.query(\"SELECT 1\").get();\n}\n","aggregatedOutputTruncated":false,"aggregatedOutputOriginalChars":1547,"aggregatedOutputReturnedChars":1547,"compressionStrategy":"none","aggregation":{"truncated":false,"strategy":"none","originalChars":1547,"returnedChars":1547,"omittedReason":"large_codex_command_execution_output","contentHash":"sha256:dfdff615e50de11275b0faf27e94711264d69d4aa3191db6a50940543486d56b","providerEventRef":"item_25"},"exitCode":0,"status":"completed","fullProviderEventAvailable":true,"providerEvent":{"type":"item.completed","item":{"id":"item_25","type":"command_execution","command":"/bin/zsh -lc \"sed -n ''1,240p'' api/db/sqlite.ts\"","aggregated_output":"import { Database } from \"bun:sqlite\";\nimport type { BunSQLiteDatabase } from \"drizzle-orm/bun-sqlite\";\nimport { drizzle } from \"drizzle-orm/bun-sqlite\";\nimport type { AppEnv } from \"../app/env\";\nimport { ensureDatabaseParentDirectory } from \"./path\";\nimport * as schema from \"./schema\";\n\nexport type AppDatabase = BunSQLiteDatabase<typeof schema>;\n\nexport type DbConnection = {\n\tclient: Database;\n\tdb: AppDatabase;\n\t/** このパッケージが接続を所有しているか（close責任があるか） */\n\townsConnection: boolean;\n};\n\nexport type DbRuntime = {\n\tdb: AppDatabase;\n\tclose: () => void;\n\tconnection: DbConnection;\n};\n\n/**\n * databasePath から新しい SQLite database を作成してDrizzleでラップする\n * 接続の所有権はこのパッケージに帰属する\n */\nexport function createDbConnection(databasePath: string): DbConnection {\n\tensureDatabaseParentDirectory(databasePath);\n\tconst client = new Database(databasePath, { create: true });\n\tconst db = drizzle(client, { schema });\n\treturn { client, db, ownsConnection: true };\n}\n\n/**\n * 外部の SQLite database をDrizzleでラップする\n * 接続の所有権はホスト側に帰属（closeしない）\n */\nexport function wrapExternalClient(client: Database): DbConnection {\n\tconst db = drizzle(client, { schema });\n\treturn { client, db, ownsConnection: false };\n}\n\nexport function createSqliteDbRuntime(env: AppEnv): DbRuntime {\n\tconst connection = createDbConnection(env.databaseUrl);\n\treturn {\n\t\tdb: connection.db,\n\t\tconnection,\n\t\tclose: () => {\n\t\t\tif (connection.ownsConnection) {\n\t\t\t\tconnection.client.close();\n\t\t\t}\n\t\t},\n\t};\n}\n\n/**\n * 接続を確立する\n */\nexport async function connectDb(client: Database) {\n\tclient.query(\"SELECT 1\").get();\n}\n","exit_code":0,"status":"completed"}},"providerEventCompacted":false,"providerEventSummary":null},"id":"a92ef13d-da7f-488a-bea4-49327e801293","seq":61}}');
