INSERT INTO "task_events" ("id", "task_run_id", "type", "message", "timestamp", "seq", "actor", "event_type", "payload_json") VALUES('3c294eb5-7ad8-4eca-b2ef-50364af783e1','2d32a4c9-0870-4a05-be99-dc27dfc69a55','info','[Codex] Command finished: /bin/zsh -lc "sed -n ''1,220p'' api/routes/auth.route.ts"',1783562239,68,'worker','tool_result','{"runEvent":{"version":1,"runId":"2d32a4c9-0870-4a05-be99-dc27dfc69a55","timestamp":"2026-07-09T01:57:19.250Z","type":"tool.call_finished","severity":"info","actor":"worker","message":"[Codex] Command finished: /bin/zsh -lc \"sed -n ''1,220p'' api/routes/auth.route.ts\"","data":{"provider":"codex","providerEventType":"item.completed","providerItemId":"item_30","toolName":"command_execution","command":"/bin/zsh -lc \"sed -n ''1,220p'' api/routes/auth.route.ts\"","commandClass":"inspection","aggregatedOutput":"import { zValidator } from \"@hono/zod-validator\";\nimport { Hono } from \"hono\";\nimport { getCookie } from \"hono/cookie\";\nimport { loginSchema } from \"../../shared/schemas/auth.schema\";\nimport type { AppEnv } from \"../app/env\";\nimport type { AuthService } from \"../modules/auth/auth.service\";\nimport {\n\tREFRESH_TOKEN_COOKIE_NAME,\n\tclearAuthCookies,\n\tsetAuthCookies,\n} from \"../modules/auth/auth-cookies\";\nimport { getAuthContextUser } from \"../modules/auth/context\";\nimport { HttpError } from \"../modules/auth/errors\";\n\ntype AuthRouteDeps = {\n\tauthService: AuthService;\n\tenv: AppEnv;\n};\n\nexport function createAuthRoute(deps: AuthRouteDeps) {\n\treturn new Hono()\n\t\t.post(\"/login\", zValidator(\"json\", loginSchema), async (c) => {\n\t\t\tconst body = c.req.valid(\"json\");\n\t\t\tconst result = await deps.authService.login({\n\t\t\t\temail: body.email,\n\t\t\t\tpassword: body.password,\n\t\t\t});\n\t\t\tsetAuthCookies(c, deps.env, result);\n\t\t\treturn c.json({ user: result.user });\n\t\t})\n\t\t.post(\"/refresh\", async (c) => {\n\t\t\tconst refreshToken = getCookie(c, REFRESH_TOKEN_COOKIE_NAME);\n\t\t\tif (!refreshToken) {\n\t\t\t\tthrow new HttpError(401, \"Unauthorized\");\n\t\t\t}\n\t\t\tconst result = await deps.authService.refresh(refreshToken);\n\t\t\tsetAuthCookies(c, deps.env, result);\n\t\t\treturn c.json({ user: result.user });\n\t\t})\n\t\t.post(\"/logout\", async (c) => {\n\t\t\tconst refreshToken = getCookie(c, REFRESH_TOKEN_COOKIE_NAME);\n\t\t\tawait deps.authService.logout(refreshToken);\n\t\t\tclearAuthCookies(c);\n\t\t\treturn c.json({ ok: true });\n\t\t})\n\t\t.get(\"/me\", async (c) => {\n\t\t\tconst authUser = getAuthContextUser(c);\n\t\t\tconst user = await deps.authService.findUserById(authUser.userId);\n\t\t\tif (!user?.isActive) {\n\t\t\t\tthrow new HttpError(401, \"Unauthorized\");\n\t\t\t}\n\t\t\treturn c.json({\n\t\t\t\tuser: {\n\t\t\t\t\tid: user.id,\n\t\t\t\t\temail: user.email,\n\t\t\t\t\tdisplayName: user.displayName,\n\t\t\t\t\trole: user.role,\n\t\t\t\t},\n\t\t\t});\n\t\t});\n}\n","aggregatedOutputTruncated":false,"aggregatedOutputOriginalChars":1862,"aggregatedOutputReturnedChars":1862,"compressionStrategy":"none","aggregation":{"truncated":false,"strategy":"none","originalChars":1862,"returnedChars":1862,"omittedReason":"large_codex_command_execution_output","contentHash":"sha256:8545d5a4b2495b23213755ab7f1890d8d3ba956ebff9d70dfb2e0222d92c9b21","providerEventRef":"item_30"},"exitCode":0,"status":"completed","fullProviderEventAvailable":true,"providerEvent":{"type":"item.completed","item":{"id":"item_30","type":"command_execution","command":"/bin/zsh -lc \"sed -n ''1,220p'' api/routes/auth.route.ts\"","aggregated_output":"import { zValidator } from \"@hono/zod-validator\";\nimport { Hono } from \"hono\";\nimport { getCookie } from \"hono/cookie\";\nimport { loginSchema } from \"../../shared/schemas/auth.schema\";\nimport type { AppEnv } from \"../app/env\";\nimport type { AuthService } from \"../modules/auth/auth.service\";\nimport {\n\tREFRESH_TOKEN_COOKIE_NAME,\n\tclearAuthCookies,\n\tsetAuthCookies,\n} from \"../modules/auth/auth-cookies\";\nimport { getAuthContextUser } from \"../modules/auth/context\";\nimport { HttpError } from \"../modules/auth/errors\";\n\ntype AuthRouteDeps = {\n\tauthService: AuthService;\n\tenv: AppEnv;\n};\n\nexport function createAuthRoute(deps: AuthRouteDeps) {\n\treturn new Hono()\n\t\t.post(\"/login\", zValidator(\"json\", loginSchema), async (c) => {\n\t\t\tconst body = c.req.valid(\"json\");\n\t\t\tconst result = await deps.authService.login({\n\t\t\t\temail: body.email,\n\t\t\t\tpassword: body.password,\n\t\t\t});\n\t\t\tsetAuthCookies(c, deps.env, result);\n\t\t\treturn c.json({ user: result.user });\n\t\t})\n\t\t.post(\"/refresh\", async (c) => {\n\t\t\tconst refreshToken = getCookie(c, REFRESH_TOKEN_COOKIE_NAME);\n\t\t\tif (!refreshToken) {\n\t\t\t\tthrow new HttpError(401, \"Unauthorized\");\n\t\t\t}\n\t\t\tconst result = await deps.authService.refresh(refreshToken);\n\t\t\tsetAuthCookies(c, deps.env, result);\n\t\t\treturn c.json({ user: result.user });\n\t\t})\n\t\t.post(\"/logout\", async (c) => {\n\t\t\tconst refreshToken = getCookie(c, REFRESH_TOKEN_COOKIE_NAME);\n\t\t\tawait deps.authService.logout(refreshToken);\n\t\t\tclearAuthCookies(c);\n\t\t\treturn c.json({ ok: true });\n\t\t})\n\t\t.get(\"/me\", async (c) => {\n\t\t\tconst authUser = getAuthContextUser(c);\n\t\t\tconst user = await deps.authService.findUserById(authUser.userId);\n\t\t\tif (!user?.isActive) {\n\t\t\t\tthrow new HttpError(401, \"Unauthorized\");\n\t\t\t}\n\t\t\treturn c.json({\n\t\t\t\tuser: {\n\t\t\t\t\tid: user.id,\n\t\t\t\t\temail: user.email,\n\t\t\t\t\tdisplayName: user.displayName,\n\t\t\t\t\trole: user.role,\n\t\t\t\t},\n\t\t\t});\n\t\t});\n}\n","exit_code":0,"status":"completed"}},"providerEventCompacted":false,"providerEventSummary":null},"id":"3c294eb5-7ad8-4eca-b2ef-50364af783e1","seq":68}}');
INSERT INTO "task_events" ("id", "task_run_id", "type", "message", "timestamp", "seq", "actor", "event_type", "payload_json") VALUES('69cfa0a5-1c15-4de4-8600-3f31f096ee1e','2d32a4c9-0870-4a05-be99-dc27dfc69a55','info','[Codex] Command finished: /bin/zsh -lc "sed -n ''1,260p'' api/routes/auth.route.test.ts"',1783562239,69,'worker','tool_result','{"runEvent":{"version":1,"runId":"2d32a4c9-0870-4a05-be99-dc27dfc69a55","timestamp":"2026-07-09T01:57:19.256Z","type":"tool.call_finished","severity":"info","actor":"worker","message":"[Codex] Command finished: /bin/zsh -lc \"sed -n ''1,260p'' api/routes/auth.route.test.ts\"","data":{"provider":"codex","providerEventType":"item.completed","providerItemId":"item_29","toolName":"command_execution","command":"/bin/zsh -lc \"sed -n ''1,260p'' api/routes/auth.route.test.ts\"","commandClass":"inspection","aggregatedOutput":"import { Hono } from \"hono\";\nimport { describe, expect, it, vi, beforeEach } from \"vitest\";\nimport { createAuthRoute } from \"./auth.route\";\nimport { requireAuth } from \"../middleware/auth\";\nimport type { AppEnv } from \"../app/env\";\nimport type { AuthService } from \"../modules/auth/auth.service\";\nimport { HttpError } from \"../modules/auth/errors\";\nimport {\n\tACCESS_TOKEN_COOKIE_NAME,\n\tREFRESH_TOKEN_COOKIE_NAME,\n} from \"../modules/auth/auth-cookies\";\n\ndescribe(\"auth route\", () => {\n\tlet app: Hono;\n\tlet mockAuthService: any;\n\tlet mockEnv: AppEnv;\n\n\tconst testUser = {\n\t\tid: \"a1a1a1a1-a1a1-41a1-a1a1-a1a1a1a1a1a1\",\n\t\temail: \"test@example.com\",\n\t\tdisplayName: \"Test User\",\n\t\trole: \"member\" as const,\n\t\tisActive: true,\n\t};\n\n\tbeforeEach(() => {\n\t\tmockEnv = {\n\t\t\tjwtSecret: \"x\".repeat(32),\n\t\t\tjwtAccessExpiresIn: \"15m\",\n\t\t\tjwtRefreshExpiresIn: \"7d\",\n\t\t\tsecureCookie: true,\n\t\t\tcookieSameSite: \"lax\",\n\t\t} as unknown as AppEnv;\n\n\t\tmockAuthService = {\n\t\t\tlogin: vi.fn(),\n\t\t\trefresh: vi.fn(),\n\t\t\tlogout: vi.fn(),\n\t\t\tfindUserById: vi.fn(),\n\t\t};\n\n\t\tapp = new Hono();\n\t\t// Set error handler to prevent throwing unhandled exceptions in tests\n\t\tapp.onError((err, c) => {\n\t\t\tconst status = (err as HttpError).status || 500;\n\t\t\treturn c.json({ message: err.message }, status as any);\n\t\t});\n\n\t\tapp.use(\n\t\t\t\"/auth/me\",\n\t\t\trequireAuth({\n\t\t\t\tenv: mockEnv,\n\t\t\t\tauthService: mockAuthService as unknown as AuthService,\n\t\t\t}),\n\t\t);\n\t\tapp.route(\n\t\t\t\"/auth\",\n\t\t\tcreateAuthRoute({\n\t\t\t\tauthService: mockAuthService as unknown as AuthService,\n\t\t\t\tenv: mockEnv,\n\t\t\t}),\n\t\t);\n\t});\n\n\tdescribe(\"POST /login\", () => {\n\t\tit(\"should login user with valid credentials and set cookies\", async () => {\n\t\t\tmockAuthService.login.mockResolvedValue({\n\t\t\t\taccessToken: \"access-token-123\",\n\t\t\t\trefreshToken: \"refresh-token-456\",\n\t\t\t\tuser: {\n\t\t\t\t\tid: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\tdisplayName: testUser.displayName,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/login\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({\n\t\t\t\t\temail: \"test@example.com\",\n\t\t\t\t\tpassword: \"password123\",\n\t\t\t\t}),\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.email).toBe(testUser.email);\n\t\t\texpect(mockAuthService.login).toHaveBeenCalledWith({\n\t\t\t\temail: \"test@example.com\",\n\t\t\t\tpassword: \"password123\",\n\t\t\t});\n\n\t\t\t// Check set-cookie headers\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(ACCESS_TOKEN_COOKIE_NAME))).toBe(\n\t\t\t\ttrue,\n\t\t\t);\n\t\t\texpect(cookies.some((c) => c.includes(REFRESH_TOKEN_COOKIE_NAME))).toBe(\n\t\t\t\ttrue,\n\t\t\t);\n\t\t});\n\n\t\tit(\"should return validation error for invalid email format\", async () => {\n\t\t\tconst res = await app.request(\"/auth/login\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({\n\t\t\t\t\temail: \"invalid-email\",\n\t\t\t\t\tpassword: \"pwd\",\n\t\t\t\t}),\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(400); // Validation error\n\t\t});\n\t});\n\n\tdescribe(\"POST /refresh\", () => {\n\t\tit(\"should refresh tokens using refresh cookie\", async () => {\n\t\t\tmockAuthService.refresh.mockResolvedValue({\n\t\t\t\taccessToken: \"new-access-token\",\n\t\t\t\trefreshToken: \"new-refresh-token\",\n\t\t\t\tuser: {\n\t\t\t\t\tid: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\tdisplayName: testUser.displayName,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/refresh\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\tCookie: `${REFRESH_TOKEN_COOKIE_NAME}=old-refresh-token`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.id).toBe(testUser.id);\n\t\t\texpect(mockAuthService.refresh).toHaveBeenCalledWith(\"old-refresh-token\");\n\n\t\t\t// New cookies should be set\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(\"new-access-token\"))).toBe(true);\n\t\t});\n\n\t\tit(\"should throw HttpError 401 when no refresh token cookie is present\", async () => {\n\t\t\tconst res = await app.request(\"/auth/refresh\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.message).toBe(\"Unauthorized\");\n\t\t});\n\t});\n\n\tdescribe(\"POST /logout\", () => {\n\t\tit(\"should call logout service and clear cookies\", async () => {\n\t\t\tconst res = await app.request(\"/auth/logout\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\tCookie: `${REFRESH_TOKEN_COOKIE_NAME}=my-refresh-token`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.ok).toBe(true);\n\t\t\texpect(mockAuthService.logout).toHaveBeenCalledWith(\"my-refresh-token\");\n\n\t\t\t// Cookies should be cleared (max-age=0 or expires in past)\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(\"Max-Age=0\") || c.includes(\"1970\"))).toBe(true);\n\t\t});\n\t});\n\n\tdescribe(\"GET /me\", () => {\n\t\tit(\"should return user details when authenticated\", async () => {\n\t\t\t// Pre-calculate a valid JWT access token\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\tmockAuthService.findUserById.mockResolvedValue(testUser);\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.email).toBe(testUser.email);\n\t\t\texpect(body.user.displayName).toBe(testUser.displayName);\n\t\t});\n\n\t\tit(\"should throw 401 when user in token is inactive in db\", async () => {\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\t// User is inactive in database\n\t\t\tmockAuthService.findUserById.mockResolvedValue({\n\t\t\t\t...testUser,\n\t\t\t\tisActive: false,\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t});\n\t});\n});\n","aggregatedOutputTruncated":false,"aggregatedOutputOriginalChars":6242,"aggregatedOutputReturnedChars":6242,"compressionStrategy":"none","aggregation":{"truncated":false,"strategy":"none","originalChars":6242,"returnedChars":6242,"omittedReason":"large_codex_command_execution_output","contentHash":"sha256:64fcf60e1473f60c5b86669a9bad1207de1331104a1fd5ffe2be20ae5a391315","providerEventRef":"item_29"},"exitCode":0,"status":"completed","fullProviderEventAvailable":true,"providerEvent":{"type":"item.completed","item":{"id":"item_29","type":"command_execution","command":"/bin/zsh -lc \"sed -n ''1,260p'' api/routes/auth.route.test.ts\"","aggregated_output":"import { Hono } from \"hono\";\nimport { describe, expect, it, vi, beforeEach } from \"vitest\";\nimport { createAuthRoute } from \"./auth.route\";\nimport { requireAuth } from \"../middleware/auth\";\nimport type { AppEnv } from \"../app/env\";\nimport type { AuthService } from \"../modules/auth/auth.service\";\nimport { HttpError } from \"../modules/auth/errors\";\nimport {\n\tACCESS_TOKEN_COOKIE_NAME,\n\tREFRESH_TOKEN_COOKIE_NAME,\n} from \"../modules/auth/auth-cookies\";\n\ndescribe(\"auth route\", () => {\n\tlet app: Hono;\n\tlet mockAuthService: any;\n\tlet mockEnv: AppEnv;\n\n\tconst testUser = {\n\t\tid: \"a1a1a1a1-a1a1-41a1-a1a1-a1a1a1a1a1a1\",\n\t\temail: \"test@example.com\",\n\t\tdisplayName: \"Test User\",\n\t\trole: \"member\" as const,\n\t\tisActive: true,\n\t};\n\n\tbeforeEach(() => {\n\t\tmockEnv = {\n\t\t\tjwtSecret: \"x\".repeat(32),\n\t\t\tjwtAccessExpiresIn: \"15m\",\n\t\t\tjwtRefreshExpiresIn: \"7d\",\n\t\t\tsecureCookie: true,\n\t\t\tcookieSameSite: \"lax\",\n\t\t} as unknown as AppEnv;\n\n\t\tmockAuthService = {\n\t\t\tlogin: vi.fn(),\n\t\t\trefresh: vi.fn(),\n\t\t\tlogout: vi.fn(),\n\t\t\tfindUserById: vi.fn(),\n\t\t};\n\n\t\tapp = new Hono();\n\t\t// Set error handler to prevent throwing unhandled exceptions in tests\n\t\tapp.onError((err, c) => {\n\t\t\tconst status = (err as HttpError).status || 500;\n\t\t\treturn c.json({ message: err.message }, status as any);\n\t\t});\n\n\t\tapp.use(\n\t\t\t\"/auth/me\",\n\t\t\trequireAuth({\n\t\t\t\tenv: mockEnv,\n\t\t\t\tauthService: mockAuthService as unknown as AuthService,\n\t\t\t}),\n\t\t);\n\t\tapp.route(\n\t\t\t\"/auth\",\n\t\t\tcreateAuthRoute({\n\t\t\t\tauthService: mockAuthService as unknown as AuthService,\n\t\t\t\tenv: mockEnv,\n\t\t\t}),\n\t\t);\n\t});\n\n\tdescribe(\"POST /login\", () => {\n\t\tit(\"should login user with valid credentials and set cookies\", async () => {\n\t\t\tmockAuthService.login.mockResolvedValue({\n\t\t\t\taccessToken: \"access-token-123\",\n\t\t\t\trefreshToken: \"refresh-token-456\",\n\t\t\t\tuser: {\n\t\t\t\t\tid: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\tdisplayName: testUser.displayName,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/login\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({\n\t\t\t\t\temail: \"test@example.com\",\n\t\t\t\t\tpassword: \"password123\",\n\t\t\t\t}),\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.email).toBe(testUser.email);\n\t\t\texpect(mockAuthService.login).toHaveBeenCalledWith({\n\t\t\t\temail: \"test@example.com\",\n\t\t\t\tpassword: \"password123\",\n\t\t\t});\n\n\t\t\t// Check set-cookie headers\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(ACCESS_TOKEN_COOKIE_NAME))).toBe(\n\t\t\t\ttrue,\n\t\t\t);\n\t\t\texpect(cookies.some((c) => c.includes(REFRESH_TOKEN_COOKIE_NAME))).toBe(\n\t\t\t\ttrue,\n\t\t\t);\n\t\t});\n\n\t\tit(\"should return validation error for invalid email format\", async () => {\n\t\t\tconst res = await app.request(\"/auth/login\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({\n\t\t\t\t\temail: \"invalid-email\",\n\t\t\t\t\tpassword: \"pwd\",\n\t\t\t\t}),\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(400); // Validation error\n\t\t});\n\t});\n\n\tdescribe(\"POST /refresh\", () => {\n\t\tit(\"should refresh tokens using refresh cookie\", async () => {\n\t\t\tmockAuthService.refresh.mockResolvedValue({\n\t\t\t\taccessToken: \"new-access-token\",\n\t\t\t\trefreshToken: \"new-refresh-token\",\n\t\t\t\tuser: {\n\t\t\t\t\tid: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\tdisplayName: testUser.displayName,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/refresh\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\tCookie: `${REFRESH_TOKEN_COOKIE_NAME}=old-refresh-token`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.id).toBe(testUser.id);\n\t\t\texpect(mockAuthService.refresh).toHaveBeenCalledWith(\"old-refresh-token\");\n\n\t\t\t// New cookies should be set\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(\"new-access-token\"))).toBe(true);\n\t\t});\n\n\t\tit(\"should throw HttpError 401 when no refresh token cookie is present\", async () => {\n\t\t\tconst res = await app.request(\"/auth/refresh\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.message).toBe(\"Unauthorized\");\n\t\t});\n\t});\n\n\tdescribe(\"POST /logout\", () => {\n\t\tit(\"should call logout service and clear cookies\", async () => {\n\t\t\tconst res = await app.request(\"/auth/logout\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\tCookie: `${REFRESH_TOKEN_COOKIE_NAME}=my-refresh-token`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.ok).toBe(true);\n\t\t\texpect(mockAuthService.logout).toHaveBeenCalledWith(\"my-refresh-token\");\n\n\t\t\t// Cookies should be cleared (max-age=0 or expires in past)\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(\"Max-Age=0\") || c.includes(\"1970\"))).toBe(true);\n\t\t});\n\t});\n\n\tdescribe(\"GET /me\", () => {\n\t\tit(\"should return user details when authenticated\", async () => {\n\t\t\t// Pre-calculate a valid JWT access token\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\tmockAuthService.findUserById.mockResolvedValue(testUser);\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.email).toBe(testUser.email);\n\t\t\texpect(body.user.displayName).toBe(testUser.displayName);\n\t\t});\n\n\t\tit(\"should throw 401 when user in token is inactive in db\", async () => {\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\t// User is inactive in database\n\t\t\tmockAuthService.findUserById.mockResolvedValue({\n\t\t\t\t...testUser,\n\t\t\t\tisActive: false,\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t});\n\t});\n});\n","exit_code":0,"status":"completed"}},"providerEventCompacted":false,"providerEventSummary":null},"id":"69cfa0a5-1c15-4de4-8600-3f31f096ee1e","seq":69}}');
