[linear-gradient(135deg,#ffffff_0%,#f2fbf7_100%)] p-6 shadow-[0_20px_60px_rgba(22,38,32,0.08)];\n+\t}\n+\n+\t.todo-kicker {\n+\t\t@apply m-0 text-xs font-extrabold uppercase tracking-[0.24em] text-brand;\n+\t}\n+\n+\t.todo-hero h1 {\n+\t\t@apply m-0 mt-2 text-[clamp(30px,5vw,48px)] leading-tight tracking-tight;\n+\t}\n+\n+\t.todo-summary {\n+\t\t@apply mt-3 max-w-[62ch] text-sm leading-6 text-muted;\n+\t}\n+\n+\t.todo-hero-card {\n+\t\t@apply grid min-w-36 gap-1 rounded-[20px] border border-brand-border bg-surface px-5 py-4 text-center;\n+\t}\n+\n+\t.todo-hero-card strong {\n+\t\t@apply text-4xl font-black text-brand;\n+\t}\n+\n+\t.todo-hero-card span {\n+\t\t@apply text-xs font-bold uppercase tracking-[0.2em] text-muted;\n+\t}\n+\n+\t.todo-grid {\n+\t\t@apply grid gap-6 lg:grid-cols-[360px_minmax(0,1fr)];\n+\t}\n+\n+\t.todo-panel {\n+\t\t@apply rounded-[20px] border border-border bg-surface p-5 shadow-[0_10px_40px_rgba(25,33,43,0.06)];\n+\t}\n+\n+\t.todo-panel-header {\n+\t\t@apply mb-4 flex items-center justify-between gap-4;\n+\t}\n+\n+\t.todo-panel-header h2 {\n+\t\t@apply m-0 text-lg font-extrabold;\n+\t}\n+\n+\t.todo-field {\n+\t\t@apply mb-4 grid gap-2;\n+\t}\n+\n+\t.todo-field span {\n+\t\t@apply text-xs font-bold uppercase tracking-[0.18em] text-muted;\n+\t}\n+\n+\t.todo-field input,\n+\t.todo-field textarea {\n+\t\t@apply rounded-control border border-border-strong bg-surface px-3 py-2 text-sm outline-none transition;\n+\t}\n+\n+\t.todo-field input:focus,\n+\t.todo-field textarea:focus {\n+\t\t@apply border-brand-border;\n+\t\tbox-shadow: 0 0 0 3px rgba(31, 122, 106, 0.14);\n+\t}\n+\n+\t.primary-button,\n+\t.secondary-button {\n+\t\t@apply inline-flex min-h-9 items-center justify-center gap-2 rounded-control px-3 font-bold;\n+\t}\n+\n+\t.primary-button {\n+\t\t@apply border border-brand bg-brand text-white;\n+\t}\n+\n+\t.secondary-button {\n+\t\t@apply border border-border-strong bg-surface text-muted-strong;\n+\t}\n+\n+\t.primary-button:hover:not(:disabled) {\n+\t\t@apply bg-brand-strong;\n+\t}\n+\n+\t.secondary-button:hover:not(:disabled) {\n+\t\t@apply bg-brand-soft text-brand;\n+\t}\n+\n+\t.todo-list-panel {\n+\t\t@apply min-w-0;\n+\t}\n+\n+\t.todo-muted {\n+\t\t@apply text-sm text-muted;\n+\t}\n+\n+\t.todo-error {\n+\t\t@apply rounded-control border border-[#efb5b5] bg-[#fff1f1] px-3 py-2 text-sm text-danger;\n+\t}\n+\n+\t.todo-list {\n+\t\t@apply grid gap-3;\n+\t}\n+\n+\t.todo-item {\n+\t\t@apply flex flex-wrap items-start justify-between gap-4 rounded-[18px] border border-border-strong bg-[#fbfcfd] p-4;\n+\t}\n+\n+\t.todo-item-main {\n+\t\t@apply min-w-0 flex-1;\n+\t}\n+\n+\t.todo-item-head {\n+\t\t@apply flex flex-wrap items-center gap-3;\n+\t}\n+\n+\t.todo-checkbox {\n+\t\t@apply flex items-center gap-2 font-extrabold;\n+\t}\n+\n+\t.todo-pill {\n+\t\t@apply rounded-pill border border-border-strong bg-white px-2.5 py-1 text-xs font-black uppercase tracking-[0.16em] text-muted;\n+\t}\n+\n+\t.todo-pill.done {\n+\t\t@apply border-brand-border bg-brand-soft text-brand;\n+\t}\n+\n+\t.todo-text,\n+\t.todo-note,\n+\t.todo-meta {\n+\t\t@apply m-0 mt-2 text-sm leading-6 text-muted;\n+\t}\n+\n+\t.todo-meta {\n+\t\t@apply flex flex-wrap gap-x-4 gap-y-1 text-xs;\n+\t}\n+\n+\t.todo-item-actions {\n+\t\t@apply flex items-center gap-2;\n+\t}\n+\n+\t.icon-button.danger {\n+\t\t@apply text-danger;\n+\t}\n+\n+\t.todo-empty {\n+\t\t@apply rounded-control border border-dashed border-border-strong px-4 py-6 text-sm text-muted;\n+\t}\n+\n \t.auth-shell {\n \t\t@apply grid min-h-[calc(100vh-64px)] place-items-center py-8;\n \t}\ndiff --git a/web/src/views/home-view.tsx b/web/src/views/home-view.tsx\nindex 416d63d..58ab2ac 100644\n--- a/web/src/views/home-view.tsx\n+++ b/web/src/views/home-view.tsx\n@@ -1,17 +1,253 @@\n+import { useMemo, useState } from \"react\";\n+import { useMutation, useQuery, useQueryClient } from \"@tanstack/react-query\";\n+import { Check, Pencil, Plus, Trash2 } from \"lucide-react\";\n+import {\n+\tcreateTodo,\n+\tdeleteTodo,\n+\tfetchTodos,\n+\ttodosQueryKey,\n+\tupdateTodo,\n+\ttype Todo,\n+} from \"../api\";\n+\n+type TodoDraft = {\n+\ttitle: string;\n+\tdescription: string;\n+\tnote: string;\n+};\n+\n+const emptyDraft: TodoDraft = {\n+\ttitle: \"\",\n+\tdescription: \"\",\n+\tnote: \"\",\n+};\n+\n+const toDraft = (todo: Todo): TodoDraft => ({\n+\ttitle: todo.title,\n+\tdescription: todo.description,\n+\tnote: todo.note,\n+});\n+\n export function HomeView() {\n+\tconst queryClient = useQueryClient();\n+\tconst { data: todos = [], isLoading, error } = useQuery({\n+\t\tqueryKey: todosQueryKey,\n+\t\tqueryFn: fetchTodos,\n+\t});\n+\tconst [draft, setDraft] = useState<TodoDraft>(emptyDraft);\n+\tconst [editingId, setEditingId] = useState<number | null>(null);\n+\n+\tconst editingTodo = useMemo(\n+\t\t() => todos.find((todo) => todo.id === editingId) ?? null,\n+\t\t[todos, editingId],\n+\t);\n+\n+\tconst refreshTodos = async () => {\n+\t\tawait queryClient.invalidateQueries({ queryKey: todosQueryKey });\n+\t};\n+\n+\tconst createMutation = useMutation({\n+\t\tmutationFn: createTodo,\n+\t\tonSuccess: async () => {\n+\t\t\tsetDraft(emptyDraft);\n+\t\t\tawait refreshTodos();\n+\t\t},\n+\t});\n+\n+\tconst updateMutation = useMutation({\n+\t\tmutationFn: updateTodo,\n+\t\tonSuccess: async () => {\n+\t\t\tsetEditingId(null);\n+\t\t\tsetDraft(emptyDraft);\n+\t\t\tawait refreshTodos();\n+\t\t},\n+\t});\n+\n+\tconst deleteMutation = useMutation({\n+\t\tmutationFn: deleteTodo,\n+\t\tonSuccess: async () => {\n+\t\t\tif (editingId !== null) setEditingId(null);\n+\t\t\tawait refreshTodos();\n+\t\t},\n+\t});\n+\n \treturn (\n-\t\t<main className=\"home-shell\">\n-\t\t\t<section className=\"home-panel\">\n-\t\t\t\t<h1>Welcome to Hono Standard</h1>\n-\t\t\t\t<p>\n-\t\t\t\t\tHono Standard is a compact full-stack starter that pairs a Hono API\n-\t\t\t\t\twith a React and Vite frontend on a single origin.\n-\t\t\t\t</p>\n-\t\t\t\t<p>\n-\t\t\t\t\tIt includes SQLite-backed authentication, httpOnly cookie sessions,\n-\t\t\t\t\ttyped routing, and a reusable component showcase without forcing login\n-\t\t\t\t\ton public screens.\n-\t\t\t\t</p>\n+\t\t<main className=\"todo-shell\">\n+\t\t\t<section className=\"todo-hero\">\n+\t\t\t\t<div>\n+\t\t\t\t\t<p className=\"todo-kicker\">todolist</p>\n+\t\t\t\t\t<h1>作成・一覧・完了管理を通す本体</h1>\n+\t\t\t\t\t<p className=\"todo-summary\">\n+\t\t\t\t\t\t作成、一覧、完了切り替え、編集、削除を1画面で扱える最小構成です。\n+\t\t\t\t\t</p>\n+\t\t\t\t</div>\n+\t\t\t\t<div className=\"todo-hero-card\">\n+\t\t\t\t\t<strong>{todos.length}</strong>\n+\t\t\t\t\t<span>total items</span>\n+\t\t\t\t</div>\n+\t\t\t</section>\n+\n+\t\t\t<section className=\"todo-grid\">\n+\t\t\t\t<form\n+\t\t\t\t\tclassName=\"todo-panel\"\n+\t\t\t\t\tonSubmit={(event) => {\n+\t\t\t\t\t\tevent.preventDefault();\n+\t\t\t\t\t\tconst payload = {\n+\t\t\t\t\t\t\ttitle: draft.title.trim(),\n+\t\t\t\t\t\t\tdescription: draft.description.trim(),\n+\t\t\t\t\t\t\tnote: draft.note.trim(),\n+\t\t\t\t\t\t};\n+\t\t\t\t\t\tif (!payload.title) return;\n+\t\t\t\t\t\tif (editingTodo) {\n+\t\t\t\t\t\t\tvoid updateMutation.mutateAsync({\n+\t\t\t\t\t\t\t\tid: editingTodo.id,\n+\t\t\t\t\t\t\t\t...payload,\n+\t\t\t\t\t\t\t\tisCompleted: editingTodo.isCompleted,\n+\t\t\t\t\t\t\t});\n+\t\t\t\t\t\t\treturn;\n+\t\t\t\t\t\t}\n+\t\t\t\t\t\tvoid createMutation.mutateAsync(payload);\n+\t\t\t\t\t}}\n+\t\t\t\t>\n+\t\t\t\t\t<div className=\"todo-panel-header\">\n+\t\t\t\t\t\t<h2>{editingTodo ? \"タスクを編集\" : \"タスクを作成\"}</h2>\n+\t\t\t\t\t\t<button type=\"submit\" className=\"primary-button\">\n+\t\t\t\t\t\t\t<Plus className=\"icon\" />\n+\t\t\t\t\t\t\t{editingTodo ? \"更新\" : \"追加\"}\n+\t\t\t\t\t\t</button>\n+\t\t\t\t\t</div>\n+\t\t\t\t\t<label className=\"todo-field\">\n+\t\t\t\t\t\t<span>Title</span>\n+\t\t\t\t\t\t<input\n+\t\t\t\t\t\t\tvalue={draft.title}\n+\t\t\t\t\t\t\tonChange={(event) =>\n+\t\t\t\t\t\t\t\tsetDraft((current) => ({ ...current, title: event.target.value }))\n+\t\t\t\t\t\t\t}\n+\t\t\t\t\t\t\tplaceholder=\"例: 新しいタスク\"\n+\t\t\t\t\t\t/>\n+\t\t\t\t\t</label>\n+\t\t\t\t\t<label className=\"todo-field\">\n+\t\t\t\t\t\t<span>Description</span>\n+\t\t\t\t\t\t<textarea\n+\t\t\t\t\t\t\tvalue={draft.description}\n+\t\t\t\t\t\t\tonChange={(event) =>\n+\t\t\t\t\t\t\t\tsetDraft((current) => ({\n+\t\t\t\t\t\t\t\t\t...current,\n+\t\t\t\t\t\t\t\t\tdescription: event.target.value,\n+\t\t\t\t\t\t\t\t}))\n+\t\t\t\t\t\t\t}\n+\t\t\t\t\t\t\trows={3}\n+\t\t\t\t\t\t\tplaceholder=\"補足説明\"\n+\t\t\t\t\t\t/>\n+\t\t\t\t\t</label>\n+\t\t\t\t\t<label className=\"todo-field\">\n+\t\t\t\t\t\t<span>Note</span>\n+\t\t\t\t\t\t<textarea\n+\t\t\t\t\t\t\tvalue={draft.note}\n+\t\t\t\t\t\t\tonChange={(event) =>\n+\t\t\t\t\t\t\t\tsetDraft((current) => ({ ...current, note: event.target.value }))\n+\t\t\t\t\t\t\t}\n+\t\t\t\t\t\t\trows={3}\n+\t\t\t\t\t\t\tplaceholder=\"メモ\"\n+\t\t\t\t\t\t/>\n+\t\t\t\t\t</label>\n+\t\t\t\t\t{editingTodo ? (\n+\t\t\t\t\t\t<button\n+\t\t\t\t\t\t\ttype=\"button\"\n+\t\t\t\t\t\t\tclassName=\"secondary-button\"\n+\t\t\t\t\t\t\tonClick={() => {\n+\t\t\t\t\t\t\t\tsetEditingId(null);\n+\t\t\t\t\t\t\t\tsetDraft(emptyDraft);\n+\t\t\t\t\t\t\t}}\n+\t\t\t\t\t\t>\n+\t\t\t\t\t\t\t編集を解除\n+\t\t\t\t\t\t</button>\n+\t\t\t\t\t) : null}\n+\t\t\t\t</form>\n+\n+\t\t\t\t<section className=\"todo-panel todo-list-panel\">\n+\t\t\t\t\t<div className=\"todo-panel-header\">\n+\t\t\t\t\t\t<h2>一覧</h2>\n+\t\t\t\t\t\t<span className=\"todo-muted\">\n+\t\t\t\t\t\t\t{isLoading ? \"読み込み中\" : `${todos.length}件`}\n+\t\t\t\t\t\t</span>\n+\t\t\t\t\t</div>\n+\t\t\t\t\t{error ? <p className=\"todo-error\">{error.message}</p> : null}\n+\t\t\t\t\t<div className=\"todo-list\">\n+\t\t\t\t\t\t{todos.map((todo) => (\n+\t\t\t\t\t\t\t<article key={todo.id} className=\"todo-item\">\n+\t\t\t\t\t\t\t\t<div className=\"todo-item-main\">\n+\t\t\t\t\t\t\t\t\t<div className=\"todo-item-head\">\n+\t\t\t\t\t\t\t\t\t\t<label className=\"todo-checkbox\">\n+\t\t\t\t\t\t\t\t\t\t\t<input\n+\t\t\t\t\t\t\t\t\t\t\t\ttype=\"checkbox\"\n+\t\t\t\t\