INSERT INTO "activity_artifacts" ("id", "task_id", "run_id", "kind", "path", "content_text", "metadata_json", "created_at") VALUES('56713600-5272-43d8-b1f5-329dac7e4e63','7bbf5aef-5a25-4f0c-9fa6-df5a5b5d67d1',NULL,'app_blueprint','19ae04b9-1d03-4eee-a8d3-77cbeb393c58.mock-blueprint.json',unistr('{\u000a  "artifactKind": "mock_blueprint",\u000a  "id": "item_7bbf5aef-5a25-4f0c-9fa6-df5a5b5d67d1",\u000a  "name": "todolist 本体",\u000a  "version": 1,\u000a  "summary": "作成・一覧・完了管理を中心に、説明やメモも扱える最小構成の todolist 画面。編集・削除まで含めた本体導線を確認する。",\u000a  "tone": "実用的でわかりやすい。余計な装飾はなく、一覧の見通しと操作のしやすさを優先する。",\u000a  "meta": {\u000a    "intent": "todolist の本体画面として、タスクの作成、一覧確認、完了/未完了の切り替え、編集、削除を一画面で確認できる状態を作る。説明とメモを含む最小構成で、public 前提の使いやすいタスク管理導線を確認する。",\u000a    "selectedSections": [\u000a      {\u000a        "sectionType": "TopMenuSection",\u000a        "selectionReason": "一覧中心の本体画面で、作成導線と主要アクションをまとめて見せるために使う。"\u000a      },\u000a      {\u000a        "sectionType": "FormSection",\u000a        "selectionReason": "新規タスク作成と編集の入力導線を、説明やメモを含めて確認するために使う。"\u000a      },\u000a      {\u000a        "sectionType": "DataTableSection",\u000a        "selectionReason": "タスク一覧、完了状態、編集・削除・完了切り替えの主要操作を一覧で確認するために使う。"\u000a      }\u000a    ]\u000a  },\u000a  "screens": [\u000a    {\u000a      "id": "screen-main",\u000a      "name": "todolist 本体",\u000a      "path": "/",\u000a      "purpose": "タスクを新規作成し、一覧で完了状況を確認し、編集・削除・完了切り替えまで行える本体画面を確認する。",\u000a      "layout": {\u000a        "template": "single_column"\u000a      },\u000a      "sections": [\u000a        {\u000a          "id": "section-topmenu",\u000a          "name": "主要操作",\u000a          "componentName": "TopMenuSection",\u000a          "region": "header",\u000a          "selectionReason": "一覧中心の画面で、主要な導線と画面の目的を冒頭で伝えるため。",\u000a          "copy": {\u000a            "title": "todolist",\u000a            "description": "今日やることをすぐ追加して、完了状況を一覧で確認できるシンプルな本体画面。",\u000a            "primaryActionLabel": "新規タスクを追加",\u000a            "secondaryActionLabel": "完了済みを表示",\u000a            "emptyStateTitle": "タスクはまだありません",\u000a            "emptyStateDescription": "まずは1件追加して、一覧で完了管理の流れを確認してください。"\u000a          },\u000a          "dataset": {\u000a            "kind": "navigation",\u000a            "items": [\u000a              {\u000a                "label": "一覧",\u000a                "href": "/",\u000a                "active": true\u000a              },\u000a              {\u000a                "label": "完了済み",\u000a                "href": "/completed",\u000a                "active": false\u000a              },\u000a              {\u000a                "label": "新規作成",\u000a                "href": "/new",\u000a                "active": false\u000a              }\u000a            ]\u000a          }\u000a        },\u000a        {\u000a          "id": "section-form",\u000a          "name": "タスク作成・編集",\u000a          "componentName": "FormSection",\u000a          "region": "main",\u000a          "selectionReason": "説明やメモを含むタスク作成と編集の入力導線を確認するため。",\u000a          "copy": {\u000a            "title": "タスクを追加する",\u000a            "description": "タイトル、説明、メモを入れて、必要な情報をまとめて管理できるようにする。",\u000a            "primaryActionLabel": "保存する",\u000a            "secondaryActionLabel": "入力をクリア",\u000a            "emptyStateTitle": "入力項目がありません",\u000a            "emptyStateDescription": "タスク作成に必要な項目を表示できません。"\u000a          },\u000a          "dataset": {\u000a            "kind": "form",\u000a            "fields": [\u000a              {\u000a                "name": "title",\u000a                "label": "タイトル",\u000a                "type": "text",\u000a                "placeholder": "例: 夕方までに買い物をする"\u000a              },\u000a              {\u000a                "name": "description",\u000a                "label": "説明",\u000a                "type": "textarea",\u000a                "placeholder": "例: 牛乳、卵、パンを買う"\u000a              },\u000a              {\u000a                "name": "memo",\u000a                "label": "メモ",\u000a                "type": "textarea",\u000a                "placeholder": "例: 18時前に寄ると空いている"\u000a              },\u000a              {\u000a                "name": "status",\u000a                "label": "完了状態",\u000a                "type": "text",\u000a                "options": [\u000a                  "[object Object]",\u000a                  "[object Object]"\u000a                ]\u000a              }\u000a            ],\u000a            "submitLabel": "保存する"\u000a          }\u000a        },\u000a        {\u000a          "id": "section-table",\u000a          "name": "タスク一覧",\u000a          "componentName": "DataTableSection",\u000a          "region": "main",\u000a          "selectionReason": "タスクの一覧、完了状態、編集・削除、切り替え操作をまとめて確認する中心要素として使う。",\u000a          "copy": {\u000a            "title": "タスク一覧",\u000a            "description": "未完了と完了をひと目で見分けながら、編集・削除・完了切り替えを行える一覧。",\u000a            "primaryActionLabel": "完了にする",\u000a            "secondaryActionLabel": "編集する",\u000a            "emptyStateTitle": "表示できるタスクがありません",\u000a            "emptyStateDescription": "新規タスクを追加して、一覧の動作を確認してください。"\u000a          },\u000a          "dataset": {\u000a            "kind": "table",\u000a            "columns": [\u000a              {\u000a                "key": "title",\u000a                "label": "タイトル"\u000a              },\u000a              {\u000a                "key": "description",\u000a                "label": "説明"\u000a              },\u000a              {\u000a                "key": "memo",\u000a                "label": "メモ"\u000a              },\u000a              {\u000a                "key": "status",\u000a                "label": "状態"\u000a              },\u000a              {\u000a                "key": "updatedAt",\u000a                "label": "更新日"\u000a              }\u000a            ],\u000a            "rows": [\u000a              {\u000a                "id": "task-1",\u000a                "title": "朝のメール確認",\u000a                "description": "重要な返信だけ先に返す",\u000a                "memo"