tive in db\", async () => {\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\t// User is inactive in database\n\t\t\tmockAuthService.findUserById.mockResolvedValue({\n\t\t\t\t...testUser,\n\t\t\t\tisActive: false,\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t});\n\t});\n});\n","aggregatedOutputTruncated":false,"aggregatedOutputOriginalChars":6242,"aggregatedOutputReturnedChars":6242,"compressionStrategy":"none","aggregation":{"truncated":false,"strategy":"none","originalChars":6242,"returnedChars":6242,"omittedReason":"large_codex_command_execution_output","contentHash":"sha256:64fcf60e1473f60c5b86669a9bad1207de1331104a1fd5ffe2be20ae5a391315","providerEventRef":"item_29"},"exitCode":0,"status":"completed","fullProviderEventAvailable":true,"providerEvent":{"type":"item.completed","item":{"id":"item_29","type":"command_execution","command":"/bin/zsh -lc \"sed -n ''1,260p'' api/routes/auth.route.test.ts\"","aggregated_output":"import { Hono } from \"hono\";\nimport { describe, expect, it, vi, beforeEach } from \"vitest\";\nimport { createAuthRoute } from \"./auth.route\";\nimport { requireAuth } from \"../middleware/auth\";\nimport type { AppEnv } from \"../app/env\";\nimport type { AuthService } from \"../modules/auth/auth.service\";\nimport { HttpError } from \"../modules/auth/errors\";\nimport {\n\tACCESS_TOKEN_COOKIE_NAME,\n\tREFRESH_TOKEN_COOKIE_NAME,\n} from \"../modules/auth/auth-cookies\";\n\ndescribe(\"auth route\", () => {\n\tlet app: Hono;\n\tlet mockAuthService: any;\n\tlet mockEnv: AppEnv;\n\n\tconst testUser = {\n\t\tid: \"a1a1a1a1-a1a1-41a1-a1a1-a1a1a1a1a1a1\",\n\t\temail: \"test@example.com\",\n\t\tdisplayName: \"Test User\",\n\t\trole: \"member\" as const,\n\t\tisActive: true,\n\t};\n\n\tbeforeEach(() => {\n\t\tmockEnv = {\n\t\t\tjwtSecret: \"x\".repeat(32),\n\t\t\tjwtAccessExpiresIn: \"15m\",\n\t\t\tjwtRefreshExpiresIn: \"7d\",\n\t\t\tsecureCookie: true,\n\t\t\tcookieSameSite: \"lax\",\n\t\t} as unknown as AppEnv;\n\n\t\tmockAuthService = {\n\t\t\tlogin: vi.fn(),\n\t\t\trefresh: vi.fn(),\n\t\t\tlogout: vi.fn(),\n\t\t\tfindUserById: vi.fn(),\n\t\t};\n\n\t\tapp = new Hono();\n\t\t// Set error handler to prevent throwing unhandled exceptions in tests\n\t\tapp.onError((err, c) => {\n\t\t\tconst status = (err as HttpError).status || 500;\n\t\t\treturn c.json({ message: err.message }, status as any);\n\t\t});\n\n\t\tapp.use(\n\t\t\t\"/auth/me\",\n\t\t\trequireAuth({\n\t\t\t\tenv: mockEnv,\n\t\t\t\tauthService: mockAuthService as unknown as AuthService,\n\t\t\t}),\n\t\t);\n\t\tapp.route(\n\t\t\t\"/auth\",\n\t\t\tcreateAuthRoute({\n\t\t\t\tauthService: mockAuthService as unknown as AuthService,\n\t\t\t\tenv: mockEnv,\n\t\t\t}),\n\t\t);\n\t});\n\n\tdescribe(\"POST /login\", () => {\n\t\tit(\"should login user with valid credentials and set cookies\", async () => {\n\t\t\tmockAuthService.login.mockResolvedValue({\n\t\t\t\taccessToken: \"access-token-123\",\n\t\t\t\trefreshToken: \"refresh-token-456\",\n\t\t\t\tuser: {\n\t\t\t\t\tid: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\tdisplayName: testUser.displayName,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/login\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({\n\t\t\t\t\temail: \"test@example.com\",\n\t\t\t\t\tpassword: \"password123\",\n\t\t\t\t}),\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.email).toBe(testUser.email);\n\t\t\texpect(mockAuthService.login).toHaveBeenCalledWith({\n\t\t\t\temail: \"test@example.com\",\n\t\t\t\tpassword: \"password123\",\n\t\t\t});\n\n\t\t\t// Check set-cookie headers\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(ACCESS_TOKEN_COOKIE_NAME))).toBe(\n\t\t\t\ttrue,\n\t\t\t);\n\t\t\texpect(cookies.some((c) => c.includes(REFRESH_TOKEN_COOKIE_NAME))).toBe(\n\t\t\t\ttrue,\n\t\t\t);\n\t\t});\n\n\t\tit(\"should return validation error for invalid email format\", async () => {\n\t\t\tconst res = await app.request(\"/auth/login\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t\t},\n\t\t\t\tbody: JSON.stringify({\n\t\t\t\t\temail: \"invalid-email\",\n\t\t\t\t\tpassword: \"pwd\",\n\t\t\t\t}),\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(400); // Validation error\n\t\t});\n\t});\n\n\tdescribe(\"POST /refresh\", () => {\n\t\tit(\"should refresh tokens using refresh cookie\", async () => {\n\t\t\tmockAuthService.refresh.mockResolvedValue({\n\t\t\t\taccessToken: \"new-access-token\",\n\t\t\t\trefreshToken: \"new-refresh-token\",\n\t\t\t\tuser: {\n\t\t\t\t\tid: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\tdisplayName: testUser.displayName,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/refresh\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\tCookie: `${REFRESH_TOKEN_COOKIE_NAME}=old-refresh-token`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.id).toBe(testUser.id);\n\t\t\texpect(mockAuthService.refresh).toHaveBeenCalledWith(\"old-refresh-token\");\n\n\t\t\t// New cookies should be set\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(\"new-access-token\"))).toBe(true);\n\t\t});\n\n\t\tit(\"should throw HttpError 401 when no refresh token cookie is present\", async () => {\n\t\t\tconst res = await app.request(\"/auth/refresh\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.message).toBe(\"Unauthorized\");\n\t\t});\n\t});\n\n\tdescribe(\"POST /logout\", () => {\n\t\tit(\"should call logout service and clear cookies\", async () => {\n\t\t\tconst res = await app.request(\"/auth/logout\", {\n\t\t\t\tmethod: \"POST\",\n\t\t\t\theaders: {\n\t\t\t\t\tCookie: `${REFRESH_TOKEN_COOKIE_NAME}=my-refresh-token`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.ok).toBe(true);\n\t\t\texpect(mockAuthService.logout).toHaveBeenCalledWith(\"my-refresh-token\");\n\n\t\t\t// Cookies should be cleared (max-age=0 or expires in past)\n\t\t\tconst cookies = res.headers.getSetCookie();\n\t\t\texpect(cookies.some((c) => c.includes(\"Max-Age=0\") || c.includes(\"1970\"))).toBe(true);\n\t\t});\n\t});\n\n\tdescribe(\"GET /me\", () => {\n\t\tit(\"should return user details when authenticated\", async () => {\n\t\t\t// Pre-calculate a valid JWT access token\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\tmockAuthService.findUserById.mockResolvedValue(testUser);\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(200);\n\t\t\tconst body = await res.json();\n\t\t\texpect(body.user.email).toBe(testUser.email);\n\t\t\texpect(body.user.displayName).toBe(testUser.displayName);\n\t\t});\n\n\t\tit(\"should throw 401 when user in token is inactive in db\", async () => {\n\t\t\tconst { generateAccessToken } = await import(\n\t\t\t\t\"../modules/auth/token.service\"\n\t\t\t);\n\t\t\tconst token = await generateAccessToken(\n\t\t\t\t{\n\t\t\t\t\tuserId: testUser.id,\n\t\t\t\t\temail: testUser.email,\n\t\t\t\t\trole: testUser.role,\n\t\t\t\t},\n\t\t\t\tmockEnv,\n\t\t\t);\n\n\t\t\t// User is inactive in database\n\t\t\tmockAuthService.findUserById.mockResolvedValue({\n\t\t\t\t...testUser,\n\t\t\t\tisActive: false,\n\t\t\t});\n\n\t\t\tconst res = await app.request(\"/auth/me\", {\n\t\t\t\theaders: {\n\t\t\t\t\tAuthorization: `Bearer ${token}`,\n\t\t\t\t},\n\t\t\t});\n\n\t\t\texpect(res.status).toBe(401);\n\t\t});\n\t});\n});\n","exit_code":0,"status":"completed"}},"providerEventCompacted":false,"providerEventSummary":null}}',NULL,NULL,'69cfa0a5-1c15-4de4-8600-3f31f096ee1e','task_event:69cfa0a5-1c15-4de4-8600-3f31f096ee1e',NULL,'visible',1783562239);
