INSERT INTO "activity_events" ("id", "task_id", "run_id", "turn_id", "parent_event_id", "seq", "run_seq", "kind", "source", "status", "text", "payload_json", "artifact_id", "client_temp_id", "external_id", "dedupe_key", "ingest_error", "visibility", "created_at") VALUES('2be7e77f-b531-4533-beab-757c3c47b667','7bbf5aef-5a25-4f0c-9fa6-df5a5b5d67d1','2d32a4c9-0870-4a05-be99-dc27dfc69a55',NULL,NULL,138,142,'tool.result','worker','completed',unistr('command_execution | /bin/zsh -lc "sed -n ''1,220p'' web/src/views/home-view.tsx" | completed | exit=0\u000aimport { useMemo, useState } from "react";\u000aimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\u000aimport { Check, Pencil, Plus, Trash2 } from "lucide-react";\u000aimport {\u000a\u0009createTodo,\u000a\u0009deleteTodo,\u000a\u0009fetchTodos,\u000a\u0009todosQueryKey,\u000a\u0009updateTodo,\u000a\u0009type Todo,\u000a} from "../api";\u000a\u000atype TodoDraft = {\u000a\u0009title: string;\u000a\u0009description: string;\u000a\u0009note: string;\u000a};\u000a\u000aconst emptyDraft: TodoDraft = {\u000a\u0009title: "",\u000a\u0009description: "",\u000a\u0009note: "",\u000a};\u000a\u000aconst toDraft = (todo: Todo): TodoDraft => ({\u000a\u0009title: todo.title,\u000a\u0009description: todo.description,\u000a\u0009note: todo.note,\u000a});\u000a\u000aexport function HomeView() {\u000a\u0009const queryClient = useQueryClient();\u000a\u0009const { data: todos = [], isLoading, error } = useQuery({\u000a\u0009\u0009queryKey: todosQueryKey,\u000a\u0009\u0009queryFn: fetchTodos,\u000a\u0009});\u000a\u0009const [draft, setDraft] = useState<TodoDraft>(emptyDraft);\u000a\u0009const [editingId, setEditingId] = useState<number | null>(null);\u000a\u000a\u0009const editingTodo = useMemo(\u000a\u0009\u0009() => todos.find((todo) => todo.id === editingId) ?? null,\u000a\u0009\u0009[todos, editingId],\u000a\u0009);\u000a\u000a\u0009const refreshTodos = async () => {\u000a\u0009\u0009await queryClient.invalida