INSERT INTO "task_run_todos" ("id", "created_at", "updated_at", "run_id", "seq", "title", "description", "task_type", "status", "procedure_id", "procedure_snapshot", "context_snapshot", "completion_gate_result", "depends_on", "status_reason", "started_at", "completed_at") VALUES('18e8d872-c259-4fd2-a02f-fef995889c2d',1783562145,1783562309,'2d32a4c9-0870-4a05-be99-dc27dfc69a55',1,'コーディング準備を行う','作業開始時に contextStill の initial_instructions と context_compile を実行し、pwd と list-dir / ls 相当で targetPath の存在・空状態・.git の有無を確認する。空または未 materialized で starter / template / clone task と判断できる場合だけ import_project を実行し、失敗・cancel・未承認なら done にせず block / fail にする。','coding_preparation','passed','coding_preparation',NULL,NULL,NULL,'[]',NULL,1783562304,1783562309);
INSERT INTO "task_run_todos" ("id", "created_at", "updated_at", "run_id", "seq", "title", "description", "task_type", "status", "procedure_id", "procedure_snapshot", "context_snapshot", "completion_gate_result", "depends_on", "status_reason", "started_at", "completed_at") VALUES('60ec2f6a-d680-45d7-8f68-89eb5cf5fd7e',1783562145,1783562815,'2d32a4c9-0870-4a05-be99-dc27dfc69a55',2,'todolist API の CRUD と完了切り替えを実装する','Hono 側に作成・一覧・更新・完了切り替え・削除の経路を追加し、shared schema で入出力を共有する。未確認仕様は固定せず、必要最小限の shape に留める。','implementation','passed',NULL,NULL,NULL,NULL,'[]',NULL,1783562309,1783562815);
INSERT INTO "task_run_todos" ("id", "created_at", "updated_at", "run_id", "seq", "title", "description", "task_type", "status", "procedure_id", "procedure_snapshot", "context_snapshot", "completion_gate_result", "depends_on", "status_reason", "started_at", "completed_at") VALUES('1f52dae1-8ac3-46f0-9b42-445651321853',1783562145,1783562820,'2d32a4c9-0870-4a05-be99-dc27dfc69a55',3,'todolist の一覧中心 UI を実装する','React/Vite 側で / の単一画面を実装し、作成・一覧・完了切り替え・編集・削除を一覧中心で扱える導線を作る。UI の細部は既存パターンに合わせ、Plan Mode での未決定事項は固定しない。','implementation','passed',NULL,NULL,NULL,NULL,'[]',NULL,1783562815,1783562820);
INSERT INTO "task_run_todos" ("id", "created_at", "updated_at", "run_id", "seq", "title", "description", "task_type", "status", "procedure_id", "procedure_snapshot", "context_snapshot", "completion_gate_result", "depends_on", "status_reason", "started_at", "completed_at") VALUES('c0ccc04f-e764-4725-b62d-9152b01f2986',1783562145,1783562825,'2d32a4c9-0870-4a05-be99-dc27dfc69a55',4,'DB migration を実行する','DB schema 変更が必要な場合は、この Todo の中で migration ファイル作成、実作業対象 DB への migration command 実行、既存 migration を使う read-only focused test / smoke 実装、その test / API / schema 確認の実行まで行う。対象 DB が不明、実 DB へ未適用、または API が no such table 等で失敗する場合は done にせず block / fail にする。隔離 DB や一時 DB の smoke は補助証跡であり、実作業対象 DB への適用確認の代替にしない。','data_migration','passed','data_migration.apply_migration',NULL,NULL,NULL,'[3]',NULL,1783562820,1783562825);
INSERT INTO "task_run_todos" ("id", "created_at", "updated_at", "run_id", "seq", "title", "description", "task_type", "status", "procedure_id", "procedure_snapshot", "context_snapshot", "completion_gate_result", "depends_on", "status_reason", "started_at", "completed_at") VALUES('873aa782-83ef-4d4b-975c-c1435304b55f',1783562269,1783562864,'2d32a4c9-0870-4a05-be99-dc27dfc69a55',5,'品質ゲート verify コマンドを通す','package.json に verify script がある場合は、このリポジトリ標準の verify コマンドを最優先で実行する。失敗した場合は原因を修正し、verify が成功するまで再実行する。verify script が無い、または環境制約で実行不能な場合だけ、typecheck / lint / test / build などの代替検証を明記して実行する。','verification','passed','quality_gate_verify',NULL,NULL,NULL,'[4]',NULL,1783562825,1783562864);
